111	    const std::shared_ptr<PeerStorage>& peerStorage,
112	    const std::shared_ptr<BtAnnounce>& btAnnounce,
113	    const std::shared_ptr<BtRuntime>& btRuntime,
114	    const std::shared_ptr<BtProgressInfoFile>& btProgressInfoFile)
115	    : downloadContext{downloadContext},
116	      pieceStorage{pieceStorage},
117	      peerStorage{peerStorage},
118	      btAnnounce{btAnnounce},
119	      btRuntime{btRuntime},
