59	  else {
60	    return getNull<DownloadContext>();
61	  }
62	}
63	
64	const std::shared_ptr<DownloadContext>&
65	BtRegistry::getDownloadContext(const std::string& infoHash) const
66	{
67	  for (auto& kv : pool_) {
68	    if (bittorrent::getTorrentAttrs(kv.second->downloadContext)->infoHash ==
69	        infoHash) {
70	      return kv.second->downloadContext;
71	    }
72	  }
73	  return getNull<DownloadContext>();
74	}
75	
76	void BtRegistry::put(a2_gid_t gid, std::unique_ptr<BtObject> obj)
77	{
78	  pool_[gid] = std::move(obj);
79	}
80	
81	BtObject* BtRegistry::get(a2_gid_t gid) const
82	{
83	  auto i = pool_.find(gid);
84	  if (i == std::end(pool_)) {
85	    return nullptr;
86	  }
87	  else {
88	    return (*i).second.get();
89	  }
90	}
91	
92	bool BtRegistry::remove(a2_gid_t gid) { return pool_.erase(gid); }
93	
94	void BtRegistry::removeAll() { pool_.clear(); }
