91	BtSetup::BtSetup() = default;
92	
93	void BtSetup::setup(std::vector<std::unique_ptr<Command>>& commands,
94	                    RequestGroup* requestGroup, DownloadEngine* e,
95	                    const Option* option)
96	{
97	  if (!requestGroup->getDownloadContext()->hasAttribute(CTX_ATTR_BT)) {
98	    return;
99	  }
100	  auto torrentAttrs =
101	      bittorrent::getTorrentAttrs(requestGroup->getDownloadContext());
102	  bool metadataGetMode = torrentAttrs->metadata.empty();
103	  auto& btReg = e->getBtRegistry();
104	  auto btObject = btReg->get(requestGroup->getGID());
105	  auto& pieceStorage = btObject->pieceStorage;
106	  auto& peerStorage = btObject->peerStorage;
107	  auto& btRuntime = btObject->btRuntime;
108	  auto& btAnnounce = btObject->btAnnounce;
109	  // commands
110	  {
111	    auto c = make_unique<TrackerWatcherCommand>(e->newCUID(), requestGroup, e);
112	    c->setPeerStorage(peerStorage);
113	    c->setPieceStorage(pieceStorage);
114	    c->setBtRuntime(btRuntime);
115	    c->setBtAnnounce(btAnnounce);
116	
117	    commands.push_back(std::move(c));
118	  }
119	  if (!metadataGetMode) {
120	    auto c = make_unique<PeerChokeCommand>(e->newCUID(), e);
121	    c->setPeerStorage(peerStorage);
122	    c->setBtRuntime(btRuntime);
123	
124	    commands.push_back(std::move(c));
125	  }
126	  {
127	    auto c = make_unique<ActivePeerConnectionCommand>(
128	        e->newCUID(), requestGroup, e, metadataGetMode ? 2_s : 10_s);
129	    c->setBtRuntime(btRuntime);
130	    c->setPieceStorage(pieceStorage);
131	    c->setPeerStorage(peerStorage);
132	    c->setBtAnnounce(btAnnounce);
133	
134	    commands.push_back(std::move(c));
135	  }
136	
137	  if (metadataGetMode || !torrentAttrs->privateTorrent) {
138	    if (DHTRegistry::isInitialized()) {
139	      auto command =
140	          make_unique<DHTGetPeersCommand>(e->newCUID(), requestGroup, e);
141	      command->setTaskQueue(DHTRegistry::getData().taskQueue.get());
142	      command->setTaskFactory(DHTRegistry::getData().taskFactory.get());
143	      command->setBtRuntime(btRuntime);
144	      command->setPeerStorage(peerStorage);
145	      commands.push_back(std::move(command));
146	    }
147	    if (DHTRegistry::isInitialized6()) {
148	      auto command =
149	          make_unique<DHTGetPeersCommand>(e->newCUID(), requestGroup, e);
150	      command->setTaskQueue(DHTRegistry::getData6().taskQueue.get());
151	      command->setTaskFactory(DHTRegistry::getData6().taskFactory.get());
152	      command->setBtRuntime(btRuntime);
153	      command->setPeerStorage(peerStorage);
154	      commands.push_back(std::move(command));
155	    }
156	  }
157	  if (!metadataGetMode) {
158	    auto unionCri = make_unique<UnionSeedCriteria>();
159	    if (option->defined(PREF_SEED_TIME)) {
160	      unionCri->addSeedCriteria(
161	          make_unique<TimeSeedCriteria>(std::chrono::seconds(
162	              static_cast<int>(option->getAsDouble(PREF_SEED_TIME) * 60))));
163	    }
164	    {
165	      double ratio = option->getAsDouble(PREF_SEED_RATIO);
166	      if (ratio > 0.0) {
167	        auto cri = make_unique<ShareRatioSeedCriteria>(
168	            option->getAsDouble(PREF_SEED_RATIO),
169	            requestGroup->getDownloadContext());
170	        cri->setPieceStorage(pieceStorage);
171	        cri->setBtRuntime(btRuntime);
172	
173	        unionCri->addSeedCriteria(std::move(cri));
174	      }
175	    }
176	    if (!unionCri->getSeedCriterion().empty()) {
177	      auto c = make_unique<SeedCheckCommand>(e->newCUID(), requestGroup, e,
178	                                             std::move(unionCri));
179	      c->setPieceStorage(pieceStorage);
180	      c->setBtRuntime(btRuntime);
181	      commands.push_back(std::move(c));
182	    }
183	  }
184	  if (btReg->getTcpPort() == 0) {
185	    static int families[] = {AF_INET, AF_INET6};
186	    size_t familiesLength =
187	        e->getOption()->getAsBool(PREF_DISABLE_IPV6) ? 1 : 2;
188	    for (size_t i = 0; i < familiesLength; ++i) {
189	      auto command =
190	          make_unique<PeerListenCommand>(e->newCUID(), e, families[i]);
191	      bool ret;
192	      uint16_t port;
193	      if (btReg->getTcpPort()) {
194	        SegList<int> sgl;
195	        int usedPort = btReg->getTcpPort();
196	        sgl.add(usedPort, usedPort + 1);
197	        ret = command->bindPort(port, sgl);
198	      }
199	      else {
200	        auto sgl =
201	            util::parseIntSegments(e->getOption()->get(PREF_LISTEN_PORT));
202	        sgl.normalize();
203	        ret = command->bindPort(port, sgl);
204	      }
205	      if (ret) {
206	        btReg->setTcpPort(port);
207	        // Add command to DownloadEngine directly.
208	        e->addCommand(std::move(command));
209	      }
210	    }
211	    if (btReg->getTcpPort() == 0) {
212	      throw DL_ABORT_EX(_("Errors occurred while binding port.\n"));
213	    }
214	  }
215	  btAnnounce->setTcpPort(btReg->getTcpPort());
216	
217	  if (option->getAsBool(PREF_BT_ENABLE_LPD) && btReg->getTcpPort() &&
218	      (metadataGetMode || !torrentAttrs->privateTorrent)) {
219	    if (!btReg->getLpdMessageReceiver()) {
220	      A2_LOG_INFO("Initializing LpdMessageReceiver.");
221	      auto receiver = std::make_shared<LpdMessageReceiver>(LPD_MULTICAST_ADDR,
222	                                                           LPD_MULTICAST_PORT);
223	      bool initialized = false;
224	      const std::string& lpdInterface =
225	          e->getOption()->get(PREF_BT_LPD_INTERFACE);
226	      if (lpdInterface.empty()) {
227	        if (receiver->init("")) {
228	          initialized = true;
229	        }
230	      }
231	      else {
232	        auto ifAddrs = SocketCore::getInterfaceAddress(lpdInterface, AF_INET,
233	                                                       AI_NUMERICHOST);
234	        for (const auto& soaddr : ifAddrs) {
235	          char host[NI_MAXHOST];
236	          if (inetNtop(AF_INET, &soaddr.su.in.sin_addr, host, sizeof(host)) ==
237	                  0 &&
238	              receiver->init(host)) {
239	            initialized = true;
240	            break;
241	          }
242	        }
243	      }
244	      if (initialized) {
245	        btReg->setLpdMessageReceiver(receiver);
246	        A2_LOG_INFO(fmt("LpdMessageReceiver initialized. multicastAddr=%s:%u,"
247	                        " localAddr=%s",
248	                        LPD_MULTICAST_ADDR, LPD_MULTICAST_PORT,
249	                        receiver->getLocalAddress().c_str()));
250	        e->addCommand(
251	            make_unique<LpdReceiveMessageCommand>(e->newCUID(), receiver, e));
252	      }
253	      else {
254	        A2_LOG_INFO("LpdMessageReceiver not initialized.");
255	      }
256	    }
257	    if (btReg->getLpdMessageReceiver()) {
258	      const unsigned char* infoHash =
259	          bittorrent::getInfoHash(requestGroup->getDownloadContext());
260	      A2_LOG_INFO("Initializing LpdMessageDispatcher.");
261	      auto dispatcher = std::make_shared<LpdMessageDispatcher>(
262	          std::string(&infoHash[0], &infoHash[INFO_HASH_LENGTH]),
263	          btReg->getTcpPort(), LPD_MULTICAST_ADDR, LPD_MULTICAST_PORT);
264	      if (dispatcher->init(btReg->getLpdMessageReceiver()->getLocalAddress(),
265	                           /*ttl*/ 1, /*loop*/ 1)) {
266	        A2_LOG_INFO("LpdMessageDispatcher initialized.");
267	        auto cmd =
268	            make_unique<LpdDispatchMessageCommand>(e->newCUID(), dispatcher, e);
269	        cmd->setBtRuntime(btRuntime);
270	        e->addCommand(std::move(cmd));
271	      }
272	      else {
273	        A2_LOG_INFO("LpdMessageDispatcher not initialized.");
274	      }
275	    }
276	  }
277	  auto btStopTimeout = option->getAsInt(PREF_BT_STOP_TIMEOUT);
278	  if (btStopTimeout > 0) {
279	    auto stopDownloadCommand = make_unique<BtStopDownloadCommand>(
280	        e->newCUID(), requestGroup, e, std::chrono::seconds(btStopTimeout));
281	    stopDownloadCommand->setBtRuntime(btRuntime);
282	    stopDownloadCommand->setPieceStorage(pieceStorage);
283	    commands.push_back(std::move(stopDownloadCommand));
284	  }
285	  btRuntime->setReady(true);
286	}
287	
