67	bool LpdReceiveMessageCommand::execute()
68	{
69	  if (e_->getRequestGroupMan()->downloadFinished() || e_->isHaltRequested()) {
70	    return true;
71	  }
72	  for (size_t i = 0; i < 20; ++i) {
73	    auto m = receiver_->receiveMessage();
74	    if (!m) {
75	      break;
76	    }
77	    auto& reg = e_->getBtRegistry();
78	    auto& dctx = reg->getDownloadContext(m->infoHash);
79	    if (!dctx) {
80	      A2_LOG_DEBUG(fmt("Download Context is null for infohash=%s.",
81	                       util::toHex(m->infoHash).c_str()));
82	      continue;
83	    }
84	    if (bittorrent::getTorrentAttrs(dctx)->privateTorrent) {
85	      A2_LOG_DEBUG("Ignore LPD message because the torrent is private.");
86	      continue;
87	    }
88	    RequestGroup* group = dctx->getOwnerRequestGroup();
89	    assert(group);
90	    auto btobj = reg->get(group->getGID());
91	    assert(btobj);
92	    auto& peerStorage = btobj->peerStorage;
